POST my-index/_search
{
  "retriever": {
    "text_similarity_reranker": {
      "retriever": {
        "standard": { "query": { "match": { "text": "reset router error 651" } } }
      },
      "field": "text",
      "inference_id": "my-rerank-endpoint",
      "inference_text": "reset router error 651",
      "rank_window_size": 100
    }
  }
}

rank-profile title-freshness inherits default {
    first-phase {
        expression { bm25(title) + 3 * freshness(timestamp) }
    }
    second-phase {
        expression { xgboost("my-model.json") }
    }
}
